nodes.text_raw:
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --bg-1: #0b1220;
  --bg-2: #152238;
  --card: rgba(255, 255, 255, 0.07);
  --card-border: rgba(255, 255, 255, 0.12);
  --text: #f4f7fb;
  --muted: rgba(244, 247, 251, 0.62);
  --accent: #7ec8ff;
  --warm: #ffb86b;
  --cool: #8ec5ff;
  --shadow: 0 30px 80px rgba(0, 0, 0, 0.45);
  --radius: 28px;
}

html, body {
  width: 1280px;
  height: 800px;
  overflow: hidden;
  font-family: "Segoe UI", system-ui, -apple-system, sans-serif;
  color: var(--text);
  background:
    radial-gradient(1200px 600px at 15% 10%, #1a3a5c 0%, transparent 55%),
    radial-gradient(900px 500px at 90% 80%, #2a1f4a 0%, transparent 50%),
    linear-gradient(160deg, var(--bg-1), var(--bg-2));
}

body {
  display: flex;
  align-items: center;
  justify-content: center;
}

.card {
  width: 980px;
  height: 620px;
  background: var(--card);
  border: 1px solid var(--card-border);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  backdrop-filter: blur(24px);
  -webkit-backdrop-filter: blur(24px);
  padding: 40px 48px 36px;
  display: flex;
  flex-direction: column;
  position: relative;
  overflow: hidden;
}

.card::before {
  content: "";
  position: absolute;
  inset: -40% auto auto -20%;
  width: 420px;
  height: 420px;
  background: radial-gradient(circle, rgba(126, 200, 255, 0.18), transparent 70%);
  pointer-events: none;
}

.card::after {
  content: "";
  position: absolute;
  inset: auto -10% -30% auto;
  width: 380px;
  height: 380px;
  background: radial-gradient(circle, rgba(255, 184, 107, 0.12), transparent 70%);
  pointer-events: none;
}

.top {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  position: relative;
  z-index: 1;
}

.location {
  font-size: 34px;
  font-weight: 650;
  letter-spacing: -0.02em;
  line-height: 1.15;
}

.date-label {
  margin-top: 8px;
  font-size: 16px;
  color: var(--muted);
  font-weight: 500;
  letter-spacing: 0.02em;
}

.badge {
  padding: 8px 14px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.08);
  border: 1px solid rgba(255, 255, 255, 0.1);
  font-size: 13px;
  color: var(--muted);
  letter-spacing: 0.04em;
  text-transform: uppercase;
  font-weight: 600;
}

.main {
  flex: 1;
  display: grid;
  grid-template-columns: 1.1fr 0.9fr;
  gap: 28px;
  align-items: center;
  position: relative;
  z-index: 1;
  min-height: 0;
}

.condition-block {
  display: flex;
  flex-direction: column;
  gap: 18px;
}

.icon-row {
  display: flex;
  align-items: center;
  gap: 22px;
}

.wx-icon {
  width: 110px;
  height: 110px;
  border-radius: 28px;
  display: grid;
  place-items: center;
  font-size: 64px;
  background: linear-gradient(145deg, rgba(255,255,255,0.14), rgba(255,255,255,0.04));
  border: 1px solid rgba(255,255,255,0.12);
  box-shadow: inset 0 1px 0 rgba(255,255,255,0.15);
}

.condition-text {
  font-size: 28px;
  font-weight: 600;
  letter-spacing: -0.01em;
}

.condition-sub {
  margin-top: 6px;
  font-size: 15px;
  color: var(--muted);
}

.temps {
  display: flex;
  gap: 18px;
}

.temp-box {
  flex: 1;
  padding: 18px 20px;
  border-radius: 18px;
  background: rgba(255, 255, 255, 0.06);
  border: 1px solid rgba(255, 255, 255, 0.08);
}

.temp-box .label {
  font-size: 12px;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--muted);
  font-weight: 650;
  margin-bottom: 8px;
}

.temp-box .value {
  font-size: 40px;
  font-weight: 700;
  letter-spacing: -0.03em;
  line-height: 1;
}

.temp-box.max .value { color: var(--warm); }
.temp-box.min .value { color: var(--cool); }

.temp-box .unit {
  font-size: 20px;
  font-weight: 500;
  opacity: 0.75;
  margin-left: 2px;
}

.hourly-panel {
  height: 100%;
  min-height: 280px;
  border-radius: 22px;
  background: rgba(0, 0, 0, 0.18);
  border: 1px solid rgba(255, 255, 255, 0.08);
  padding: 20px 18px 16px;
  display: flex;
  flex-direction: column;
}

.hourly-title {
  font-size: 13px;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--muted);
  font-weight: 650;
  margin-bottom: 14px;
  padding-left: 6px;
}

.hourly-scroll {
  flex: 1;
  overflow-x: auto;
  overflow-y: hidden;
  display: flex;
  align-items: stretch;
  gap: 8px;
  padding-bottom: 6px;
  scrollbar-width: thin;
  scrollbar-color: rgba(255,255,255,0.25) transparent;
}

.hourly-scroll::-webkit-scrollbar { height: 6px; }
.hourly-scroll::-webkit-scrollbar-thumb {
  background: rgba(255,255,255,0.25);
  border-radius: 99px;
}

.hour-col {
  flex: 0 0 52px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: flex-end;
  gap: 8px;
  padding: 4px 0;
}

.hour-temp {
  font-size: 13px;
  font-weight: 650;
  color: var(--text);
}

.hour-bar-wrap {
  width: 100%;
  flex: 1;
  display: flex;
  align-items: flex-end;
  justify-content: center;
  min-height: 120px;
}

.hour-bar {
  width: 14px;
  border-radius: 99px;
  background: linear-gradient(180deg, var(--accent), rgba(126, 200, 255, 0.25));
  min-height: 8px;
  transition: height 0.4s ease;
}

.hour-label {
  font-size: 11px;
  color: var(--muted);
  font-weight: 600;
  font-variant-numeric: tabular-nums;
}

.footer {
  margin-top: 8px;
  position: relative;
  z-index: 1;
  display: flex;
  justify-content: space-between;
  align-items: center;
  color: var(--muted);
  font-size: 12px;
  letter-spacing: 0.02em;
}

.status {
  display: none;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 14px;
  height: 100%;
  text-align: center;
  position: relative;
  z-index: 1;
}

.status.visible { display: flex; }
.content.hidden { display: none; }

.status-icon {
  font-size: 48px;
  opacity: 0.9;
}

.status-title {
  font-size: 24px;
  font-weight: 650;
}

.status-msg {
  font-size: 15px;
  color: var(--muted);
  max-width: 420px;
  line-height: 1.5;
}

.loader {
  width: 42px;
  height: 42px;
  border-radius: 50%;
  border: 3px solid rgba(255,255,255,0.12);
  border-top-color: var(--accent);
  animation: spin 0.85s linear infinite;
}

@keyframes spin { to { transform: rotate(360deg); } }

(function () {
  const WMO = {
    0:  { label: "Clear sky", emoji: "☀️" },
    1:  { label: "Mainly clear", emoji: "🌤️" },
    2:  { label: "Partly cloudy", emoji: "⛅" },
    3:  { label: "Overcast", emoji: "☁️" },
    45: { label: "Fog", emoji: "🌫️" },
    48: { label: "Depositing rime fog", emoji: "🌫️" },
    51: { label: "Light drizzle", emoji: "🌦️" },
    53: { label: "Moderate drizzle", emoji: "🌦️" },
    55: { label: "Dense drizzle", emoji: "🌧️" },
    56: { label: "Light freezing drizzle", emoji: "🌧️" },
    57: { label: "Dense freezing drizzle", emoji: "🌧️" },
    61: { label: "Slight rain", emoji: "🌧️" },
    63: { label: "Moderate rain", emoji: "🌧️" },
    65: { label: "Heavy rain", emoji: "🌧️" },
    66: { label: "Light freezing rain", emoji: "🌧️" },
    67: { label: "Heavy freezing rain", emoji: "🌧️" },
    71: { label: "Slight snow", emoji: "🌨️" },
    73: { label: "Moderate snow", emoji: "❄️" },
    75: { label: "Heavy snow", emoji: "❄️" },
    77: { label: "Snow grains", emoji: "🌨️" },
    80: { label: "Slight rain showers", emoji: "🌦️" },
    81: { label: "Moderate rain showers", emoji: "🌧️" },
    82: { label: "Violent rain showers", emoji: "⛈️" },
    85: { label: "Slight snow showers", emoji: "🌨️" },
    86: { label: "Heavy snow showers", emoji: "❄️" },
    95: { label: "Thunderstorm", emoji: "⛈️" },
    96: { label: "Thunderstorm with slight hail", emoji: "⛈️" },
    99: { label: "Thunderstorm with heavy hail", emoji: "⛈️" }
  };

  function todayUTC() {
    return new Date().toISOString().slice(0, 10);
  }

  function parseParams() {
    const q = new URLSearchParams(window.location.search);
    const lat = parseFloat(q.get("lat"));
    const lon = parseFloat(q.get("lon"));
    const name = (q.get("name") || "").trim() || "Berlin";
    let date = (q.get("date") || "").trim();
    if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) date = todayUTC();
    return {
      lat: Number.isFinite(lat) ? lat : 52.52,
      lon: Number.isFinite(lon) ? lon : 13.405,
      name,
      date
    };
  }

  function formatDisplayDate(iso) {
    const [y, m, d] = iso.split("-").map(Number);
    const dt = new Date(Date.UTC(y, m - 1, d));
    return dt.toLocaleDateString("en-US", {
      weekday: "long",
      year: "numeric",
      month: "long",
      day: "numeric",
      timeZone: "UTC"
    });
  }

  function showError(title, msg) {
    document.getElementById("loader").style.display = "none";
    document.getElementById("statusTitle").textContent = title;
    document.getElementById("statusMsg").textContent = msg;
    document.getElementById("status").classList.add("visible");
    document.getElementById("content").classList.add("hidden");
    const icon = document.querySelector(".status-icon");
    if (!icon) {
      const el = document.createElement("div");
      el.className = "status-icon";
      el.textContent = "⚠️";
      document.getElementById("status").insertBefore(el, document.getElementById("statusTitle"));
    }
  }

  function weatherInfo(code) {
    return WMO[code] || { label: "Unknown conditions", emoji: "🌡️" };
  }

  function buildHourly(times, temps) {
    const root = document.getElementById("hourly");
    root.innerHTML = "";
    if (!times || !temps || !times.length) {
      root.innerHTML = '<div style="color:var(--muted);padding:12px;font-size:14px;">No hourly data available</div>';
      return;
    }

    const valid = temps.filter(t => t != null && !Number.isNaN(t));
    const minT = Math.min(...valid);
    const maxT = Math.max(...valid);
    const span = Math.max(maxT - minT, 1);

    times.forEach((t, i) => {
      const temp = temps[i];
      if (temp == null || Number.isNaN(temp)) return;
      const hour = t.slice(11, 13);
      const col = document.createElement("div");
      col.className = "hour-col";
      const heightPct = 18 + ((temp - minT) / span) * 82;
      col.innerHTML =
        '<div class="hour-temp">' + Math.round(temp) + '°</div>' +
        '<div class="hour-bar-wrap"><div class="hour-bar" style="height:' + heightPct + '%"></div></div>' +
        '<div class="hour-label">' + hour + '</div>';
      root.appendChild(col);
    });
  }

  async function load() {
    const { lat, lon, name, date } = parseParams();
    const isPast = date < todayUTC();
    const endpoint = isPast ? "/api/om/archive" : "/api/om/forecast";

    const params = new URLSearchParams({
      latitude: String(lat),
      longitude: String(lon),
      daily: "temperature_2m_max,temperature_2m_min,weather_code",
      hourly: "temperature_2m",
      timezone: "UTC",
      temperature_unit: "celsius",
      start_date: date,
      end_date: date
    });

    let res;
    try {
      res = await fetch(endpoint + "?" + params.toString());
    } catch (e) {
      showError("Unable to load weather", "A network error occurred while contacting the weather service.");
      return;
    }

    if (!res.ok) {
      showError("Unable to load weather", "The weather service returned an error (" + res.status + ").");
      return;
    }

    let data;
    try {
      data = await res.json();
    } catch (e) {
      showError("Unable to load weather", "The weather response could not be parsed.");
      return;
    }

    const daily = data.daily;
    const hourly = data.hourly;
    if (!daily || !daily.time || !daily.time.length) {
      showError("Unable to load weather", "No weather data is available for this location and date.");
      return;
    }

    const idx = 0;
    const tMax = daily.temperature_2m_max[idx];
    const tMin = daily.temperature_2m_min[idx];
    const code = daily.weather_code[idx];
    const info = weatherInfo(code);

    document.getElementById("locationName").textContent = name;
    document.getElementById("dateLabel").textContent = formatDisplayDate(date);
    document.getElementById("sourceBadge").textContent = isPast ? "Historical" : "Forecast";
    document.getElementById("wxIcon").textContent = info.emoji;
    document.getElementById("conditionText").textContent = info.label;
    document.getElementById("conditionSub").textContent =
      "Weather code " + code + " · " + (isPast ? "Archive data" : "Forecast data");
    document.getElementById("tempMax").textContent =
      tMax == null || Number.isNaN(tMax) ? "—" : String(Math.round(tMax));
    document.getElementById("tempMin").textContent =
      tMin == null || Number.isNaN(tMin) ? "—" : String(Math.round(tMin));
    document.getElementById("coords").textContent =
      lat.toFixed(4) + "°, " + lon.toFixed(4) + "°";

    buildHourly(hourly && hourly.time, hourly && hourly.temperature_2m);

    document.getElementById("status").classList.remove("visible");
    document.getElementById("content").classList.remove("hidden");
  }

  load();
})();
